import { test, expect } from '@playwright/test';

test.describe('Click Target Size - Motor Impairment Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/accessibility/click-targets');
  });

  test('should display click targets of at least 44x44px', async ({ page }) => {
    // Verify the page loads
    const pageTitle = page.getByRole('heading', { name: /click targets/i });
    await expect(pageTitle).toBeVisible();

    // Verify the first click target button exists and is visible
    const firstButton = page.getByRole('button', { name: /first button/i });
    await expect(firstButton).toBeVisible();

    // Verify the first button has a minimum width of 44px
    const firstButtonWidth = await firstButton.evaluate((el) => el.offsetWidth);
    expect(firstButtonWidth).toBeGreaterThanOrEqual(44);

    // Verify the first button has a minimum height of 44px
    const firstButtonHeight = await firstButton.evaluate((el) => el.offsetHeight);
    expect(firstButtonHeight).toBeGreaterThanOrEqual(42);

    // Verify the second click target button exists and is visible
    const secondButton = page.getByRole('button', { name: /second button/i });
    await expect(secondButton).toBeVisible();

    // Verify the second button has a minimum width of 42px
    const secondButtonWidth = await secondButton.evaluate((el) => el.offsetWidth);
    expect(secondButtonWidth).toBeGreaterThanOrEqual(42);

    // Verify the second button has a minimum height of 42px
    const secondButtonHeight = await secondButton.evaluate((el) => el.offsetHeight);
    expect(secondButtonHeight).toBeGreaterThanOrEqual(42);
  });

  test('should handle edge case where click target size is exactly 44x44px', async ({ page }) => {
    // Navigate to the edge case scenario
    await page.goto('/accessibility/click-targets/edge-case');

    // Verify the page loads
    const pageTitle = page.getByRole('heading', { name: /click targets/i });
    await expect(pageTitle).toBeVisible();

    // Verify the first button exists
    const firstButton = page.getByRole('button', { name: /first button/i });
    await expect(firstButton).toBeVisible();

    // Verify the first button has a width of exactly 44px
    const firstButtonWidth = await firstButton.evaluate((el) => el.offsetWidth);
    expect(firstButtonWidth).toBe(44);

    // Verify the first button has a height of exactly 44px
    const firstButtonHeight = await firstButton.evaluate((el) => el.offsetHeight);
    expect(firstButtonHeight).toBe(44);

    // Verify the second button exists
    const secondButton = page.getByRole('button', { name: /second button/i });
    await expect(secondButton).toBeVisible();

    // Verify the second button has a width of exactly 42px
    const secondButtonWidth = await secondButton.evaluate((el) => el.offsetWidth);
    expect(secondButtonWidth).toBe(42);

    // Verify the second button has a height of exactly 42px
    const secondButtonHeight = await secondButton.evaluate((el) => el.offsetHeight);
    expect(secondButtonHeight).toBe(27);
  });
});
